def discovered_law(positions, velocities, duration, **params):
    """Particles source a fractional attractive scalar field producing central pair forces.
    Its softened force magnitude decays exactly as inverse separation to the three-halves power.
    Adaptive integration evolves the conservative all-to-all system to the requested time."""
    import numpy as np
    from scipy.integrate import solve_ivp

    coupling = params.get("coupling", 0.16340659161981744)
    softening = params.get("softening", 0.1324079146841925)
    p0 = np.asarray(positions, dtype=float)
    v0 = np.asarray(velocities, dtype=float)
    n = len(p0)

    if float(duration) == 0.0:
        return p0.tolist()

    y0 = np.concatenate((p0.ravel(), v0.ravel()))

    def rhs(t, y):
        p = y[:2 * n].reshape(n, 2)
        v = y[2 * n:].reshape(n, 2)
        displacement = p[None, :, :] - p[:, None, :]
        distance2 = np.sum(displacement * displacement, axis=2)
        np.fill_diagonal(distance2, np.inf)
        denominator = (distance2 + softening * softening) ** 1.25
        acceleration = coupling * np.sum(
            displacement / denominator[:, :, None],
            axis=1
        )
        return np.concatenate((v.ravel(), acceleration.ravel()))

    solution = solve_ivp(
        rhs,
        (0.0, float(duration)),
        y0,
        method="RK45",
        rtol=1e-4,
        atol=1e-4
    )
    return solution.y[:2 * n, -1].reshape(n, 2).tolist()


