def discovered_law(pos1, pos2, p1, p2, velocity2, duration, **params):
    """
    An isotropic point source in an effective noninteger dimension produces a fractional power-law field.
    Its amplitude scales with p1 while the probe response scales inversely with p2.
    The resulting motion is conservative and velocity independent, with a small regularized core.
    """
    from scipy.integrate import solve_ivp

    if duration <= 0.0:
        return [float(pos2[0]), float(pos2[1])], [float(velocity2[0]), float(velocity2[1])]

    coupling = params.get("coupling", 0.18937117481225593)
    radial_power = params.get("radial_power", 1.1100573086395265)
    softening = params.get("softening", 0.03228875250488272)

    def rhs(t, state):
        x, y, vx, vy = state
        dx = x - pos1[0]
        dy = y - pos1[1]
        radius_squared = dx * dx + dy * dy + softening * softening
        scale = -coupling * (p1 / p2) / (
            radius_squared ** ((radial_power + 1.0) / 2.0)
        )
        return [vx, vy, scale * dx, scale * dy]

    initial_state = [
        float(pos2[0]),
        float(pos2[1]),
        float(velocity2[0]),
        float(velocity2[1]),
    ]
    solution = solve_ivp(
        rhs,
        (0.0, float(duration)),
        initial_state,
        method="RK45",
        rtol=1e-5,
        atol=1e-7,
    )
    final_state = solution.y[:, -1]
    return final_state[:2].tolist(), final_state[2:].tolist()


