    The anchor generates a softened logarithmic central field in two dimensions.
    All other particles are passive tracers whose reported masses do not affect the dynamics.
    An outward harmonic field competes with the anchor's attraction.
    """
    import numpy as np
    from scipy.integrate import solve_ivp

    alpha = params.get("alpha", 0.05039314213613213)
    mu = params.get("mu", 7.902881174597241)
    soft = params.get("soft", 0.20428367295259148)

    p0 = np.asarray(positions, dtype=float)
    v0 = np.asarray(velocities, dtype=float)
    n = len(p0)
    y0 = np.concatenate((p0.ravel(), v0.ravel()))

    def rhs(t, y):
        p = y[:2 * n].reshape(n, 2)
        v = y[2 * n:].reshape(n, 2)
        relative = p - p[0]
        radius_squared = np.sum(relative * relative, axis=1) + soft * soft
        acceleration = (
            alpha * relative
            - mu * relative / radius_squared[:, None]
        )
        acceleration[0] = 0.0
        return np.concatenate((v.ravel(), acceleration.ravel()))

    solution = solve_ivp(
        rhs,
        (0.0, duration),
        y0,
        method="RK45",
        rtol=1e-5,
        atol=1e-6
    )
    return solution.y[:2 * n, -1].reshape(n, 2).tolist()


