    """
    The universe is governed by a fixed central radial field anchored at the origin.
    The acceleration has constant circular-speed form, proportional to minus position divided by radius squared.
    Particle masses do not affect probe acceleration; a small softening only regularizes near-origin passages.
    """
    import numpy as np
    from scipy.integrate import solve_ivp

    pos0 = np.asarray(positions, dtype=float)
    vel0 = np.asarray(velocities, dtype=float)
    n = pos0.shape[0]
    soft = params.get("soft", 0.15)

    if duration <= 0:
        return pos0.tolist()

    y0 = np.concatenate([pos0.reshape(-1), vel0.reshape(-1)])

    def rhs(t, y):
        r = y[:2*n].reshape(n, 2)
        v = y[2*n:].reshape(n, 2)
        r2 = np.sum(r*r, axis=1) + soft*soft
        a = -8.0 * r / r2[:, None]
        a[0] = 0.0
        return np.concatenate([v.reshape(-1), a.reshape(-1)])

    sol = solve_ivp(rhs, (0.0, float(duration)), y0, method="RK45", rtol=1e-4, atol=1e-4)
    yf = sol.y[:, -1]
    return yf[:2*n].reshape(n, 2).tolist()

