def discovered_law(positions, velocities, duration):
    import numpy as np
    from scipy.integrate import solve_ivp

    y0 = np.concatenate([np.array(positions).flatten(), np.array(velocities).flatten()])

    def rhs(t, y):
        N = len(positions)
        pos = y[:2*N].reshape(N, 2)
        vel = y[2*N:].reshape(N, 2)

        acc = np.zeros((N, 2))

        for i in range(N):
            f = np.zeros(2)
            for j in range(30):
                if i == j:
                    continue
                r = pos[j] - pos[i]
                dist = np.linalg.norm(r)
                if dist > 1e-3:
                    if j < 10:
                        c = 1.0
                    elif j < 20:
                        c = -1.0
                    else:
                        c = 0.0
                    f += c * r / (dist ** 3)

            f -= 0.1 * vel[i]
            acc[i] = f

        return np.concatenate([vel.flatten(), acc.flatten()])

    sol = solve_ivp(rhs, (0, duration), y0, method='RK45', rtol=1e-4, atol=1e-4)
    return sol.y[:2*N, -1].reshape(N, 2).tolist()

